pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory tos, uint256[] memory values) public {
        // Bound inputs to avoid overflow/underflow in the multiplication check
        vm.assume(tos.length > 0 && tos.length == values.length);
        for (uint i = 0; i < tos.length; i++) {
            // Ensure the require((v[i] == 0) || ...) passes
            vm.assume(values[i] == 0 || (values[i] * 1e18) / values[i] == 1e18);
            // Avoid zero address that might cause revert in low-level call (but reference allows)
            tos[i] = address(uint160(bound(uint160(tos[i]), 1, type(uint160).max)));
        }

        // Use the expected caller prank to satisfy msg.sender
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);

        // Execute transfer via low-level call to capture return value
        (bool success, bytes memory retData) = address(c).call(
            abi.encodeWithSelector(c.transfer.selector, tos, values)
        );

        // The reference ensures that if it doesn't revert, it returns true
        assertTrue(success && abi.decode(retData, (bool)) == true);
    }
}

